const EventEmitter = require('events');
const eventBus = new EventEmitter();

// --- THE SUBSCRIBERS (Decoupled Services) ---
class EmailService {
  constructor() { eventBus.on('purchase', this.sendReceipt); }
  sendReceipt(data) { console.log(`[Email]: Receipt sent to ${data.user}`); }
}

class InventoryService {
  constructor() { eventBus.on('purchase', this.reduceStock); }
  reduceStock(data) { console.log(`[Inventory]: Reduced stock of ${data.item} by 1`); }
}

// Instantiate the services so they start listening
new EmailService();
new InventoryService();

// --- THE PUBLISHER (Checkout Route) ---
function handleCheckout(user, item) {
  console.log(`[Checkout]: Processing payment for ${item}...`);

  // Checkout logic is completely unaware of Emails or Inventory!
  // It just broadcasts the event and moves on.
  eventBus.emit('purchase', { user, item });
}

handleCheckout("alice@test.com", "MacBook Pro");
